    foreach (['roots', 'facade'] as $key) {
        if (($decoded[$key] ?? null) !== ($expected[$key] ?? null)) {
            $lines[] = "  ~ {$key}";
        }
    }

    return $lines === [] ? ['  ~ formatting'] : $lines;
}

