    }

    if ($mode === '--write') {
        file_put_contents($path, $encoded);
        fwrite(STDOUT, "updated {$package}/api-manifest.json\n");

        continue;
    }

    $stale = true;
    fwrite(STDERR, "{$package}/api-manifest.json is stale (run composer api:manifest):\n".implode("\n", apiDiff($current, $manifest))."\n");
}

exit($stale ? 1 : 0);
