    for r in rows:
        if ((r.get("owner")=="split") != split):
            continue
        for key in ("current_path","target_path"):
            for p in parts(r.get(key)):
                by_path.setdefault(p, r)

def interim(fqcn):
    if not fqcn or " + " in fqcn or fqcn=="—":
        return None
    if fqcn.startswith("AzGuard\\Filament\\"):
        rel=fqcn[len("AzGuard\\Filament\\"):].replace("\\","/")
        return f"packages/filament/src/{rel}.php"
    if fqcn.startswith("AzGuard\\"):
        rel=fqcn[len("AzGuard\\"):].replace("\\","/")
        return f"packages/core/src/{rel}.php"
    return None

